import subprocess
import json
import re

def probe(ext, marker_start, marker_end=None):
    filename = f"test_probe.{ext}"
    if marker_end:
        content = f"{marker_start} comment {marker_end}\ncode"
    else:
        content = f"{marker_start} comment\ncode"
    with open(filename, "w") as f:
        f.write(content)
    try:
        res = subprocess.run(["./executable", "--format", "json", filename], capture_output=True, text=True)
        data = json.loads(res.stdout)
        if data:
            for item in data:
                if item["Name"] != "Total":
                    if item["Comment"] > 0:
                        return True
    except:
        pass
    return False

langs = []
with open("languages.txt") as f:
    for line in f:
        m = re.match(r"^(.*) \((.*)\)$", line.strip())
        if m:
            name = m.group(1)
            exts = m.group(2).split(",")
            langs.append({"name": name, "exts": exts})

single_markers = ["//", "#", "--", ";", "%", "*", "!", "'", "rem "]
multi_markers = [("/*", "*/"), ("<!--", "-->"), ("{-", "-}"), ("(*", "*)"), ("\"\"\"", "\"\"\""), ("'''", "'''")]

results = []
for lang in langs:
    ext = lang["exts"][0]
    found_single = []
    for m in single_markers:
        if probe(ext, m):
            found_single.append(m)
    found_multi = []
    for ms, me in multi_markers:
        if probe(ext, ms, me):
            found_multi.append((ms, me))
    results.append({
        "name": lang["name"],
        "exts": lang["exts"],
        "single": found_single,
        "multi": found_multi
    })
    print(f"Done {lang['name']}")

with open("lang_data.json", "w") as f:
    json.dump(results, f)
EOF
# I will only run it for a few languages first to see if it works.
head -n 20 languages.txt > languages_small.txt
sed -i 's/languages.txt/languages_small.txt/' probe_all.py
python3 probe_all.py
cat lang_data.json
"}

