with open("lang_data.json") as f:
    langs = json.load(f)

print("""package main

type Language struct {
    Name               string
    Extensions         []string
    SingleLineComments []string
    MultiLineComments  [][2]string
    ComplexityKeywords []string
}

var Languages = []Language{""")

for lang in langs:
    single = ", ".join(f'"{s}"' for s in lang["single"])
    multi = ", ".join(f'{{"{m[0]}", "{m[1]}"}}' for m in lang["multi"])
    exts = ", ".join(f'"{e}"' for e in lang["exts"])
    comp = ", ".join(f'"{c}"' for c in lang["complexity"])
