{"command":"cat <<'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
)

var (
	avgWage          = flag.Int("avg-wage", 56286, "average wage")
	projectType      = flag.String("cocomo-project-type", "organic", "COCOMO project type")
	format           = flag.String("format", "tabular", "output format")
	noCocomo         = flag.Bool("no-cocomo", false, "remove COCOMO")
	wide             = flag.Bool("wide", false, "wider output")
	excludeDir       = flag.String("exclude-dir", ".git,.hg,.svn", "exclude directories")
	versionFlag      = flag.Bool("version", false, "version")
	overhead         = flag.Float64("overhead", 2.4, "overhead")
	eaf              = flag.Float64("eaf", 1.0, "eaf")
)

func main() {
	flag.Parse()

	if *versionFlag {
		fmt.Println("scc version 3.7.0")
		return
	}

	targets := flag.Args()
	if len(targets) == 0 {
		targets = []string{"."}
	}

	excludedDirs := strings.Split(*excludeDir, ",")

	fileList := []string{}
	for _, target := range targets {
		filepath.Walk(target, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return nil
			}
			if info.IsDir() {
				for _, d := range excludedDirs {
					if info.Name() == d {
						return filepath.SkipDir
					}
				}
				return nil
			}
			fileList = append(fileList, path)
			return nil
		})
	}

	results := make(chan *FileStats, len(fileList))
	var wg sync.WaitGroup

	// Limited workers as per default (8)
	workerCount := 8
	jobs := make(chan string, len(fileList))

	for i := 0; i < workerCount; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for path := range jobs {
				stats, _ := AnalyzeFile(path)
				if stats != nil {
					results <- stats
				}
			}
		}()
	}

	for _, path := range fileList {
		jobs <- path
	}
	close(jobs)
	wg.Wait()
	close(results)

	langStats := map[string]*FileStats{}
	totalBytes := int64(0)
	for s := range results {
		totalBytes += s.Bytes
		if _, ok := langStats[s.Language]; !ok {
