{"command":"cat <<'EOF' > counter.go
package main

import (
	"bufio"
	"io"
	"os"
	"strings"
)

type FileStats struct {
	Language   string
	Files      int
	Lines      int
	Blanks     int
	Comments   int
	Code       int
	Complexity int
	Bytes      int64
}

func AnalyzeFile(path string) (*FileStats, error) {
	filename := strings.ToLower(filepathBase(path))
	ext := ""
	if idx := strings.LastIndex(filename, "."); idx != -1 {
		ext = filename[idx+1:]
	}

	lang, ok := ExtensionToLanguage[ext]
	if !ok {
		lang, ok = ExtensionToLanguage[filename]
	}
	if !ok {
		return nil, nil
	}

	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	info, _ := f.Stat()
	stats := &FileStats{
		Language: lang.Name,
		Files:    1,
		Bytes:    info.Size(),
	}

	reader := bufio.NewReader(f)
	inMultiLine := ""

	for {
		line, err := reader.ReadString('\n')
		if err != nil && err != io.EOF {
			break
		}
		if err == io.EOF && line == "" {
			break
		}

		stats.Lines++
		trimmed := strings.TrimSpace(line)

		if trimmed == "" && inMultiLine == "" {
			stats.Blanks++
		} else {
			isCode := false
			isComment := false

			lineRemainder := line

			if inMultiLine != "" {
				isComment = true
				if idx := strings.Index(lineRemainder, inMultiLine); idx != -1 {
					lineRemainder = lineRemainder[idx+len(inMultiLine):]
					inMultiLine = ""
					// Continue checking the rest of the line
				} else {
					lineRemainder = ""
				}
			}

			for lineRemainder != "" {
				trimmedRemainder := strings.TrimSpace(lineRemainder)
				if trimmedRemainder == "" {
					break
				}

				// Check single line comments
				foundSLC := false
				for _, slc := range lang.SingleLineComments {
					if strings.HasPrefix(trimmedRemainder, slc) {
						isComment = true
						foundSLC = true
						break
					}
				}
				if foundSLC {
					break
				}

				// Check multi line start
				foundMLC := false
				for _, mlc := range lang.MultiLineComments {
					if strings.HasPrefix(trimmedRemainder, mlc[0]) {
						isComment = true
						foundMLC = true
						lineRemainder = lineRemainder[strings.Index(lineRemainder, mlc[0])+len(mlc[0]):]
						if idx := strings.Index(lineRemainder, mlc[1]); idx != -1 {
							lineRemainder = lineRemainder[idx+len(mlc[1]):]
						} else {
							inMultiLine = mlc[1]
							lineRemainder = ""
						}
						break
					}
				}
				if foundMLC {
					continue
				}

