{"command":"cat <<'EOF' > gen_languages.py
import json

with open("lang_data.json") as f:
    langs = json.load(f)

def escape(s):
    return s.replace('\\', '\\\\').replace('"', '\\"')

print("""package main

type Language struct {
    Name               string
    Extensions         []string
    SingleLineComments []string
    MultiLineComments  [][2]string
    ComplexityKeywords []string
}

var Languages = []Language{""")

for lang in langs:
    single = ", ".join(f'"{escape(s)}"' for s in lang["single"])
    multi = ", ".join(f'{{"{escape(m[0])}", "{escape(m[1])}"}}' for m in lang["multi"])
    exts = ", ".join(f'"{escape(e)}"' for e in lang["exts"])
    comp = ", ".join(f'"{escape(c)}"' for c in lang["complexity"])
    print(f'    {{Name: "{escape(lang["name"])}", Extensions: []string{{{exts}}}, SingleLineComments: []string{{{single}}}, MultiLineComments: [][2]string{{{multi}}}, ComplexityKeywords: []string{{{comp}}}}},')

print("}")

print("""
var ExtensionToLanguage = map[string]*Language{}

func init() {
    for i := range Languages {
        for _, ext := range Languages[i].Extensions {
            ExtensionToLanguage[ext] = &Languages[i]
        }
    }
}
""")
EOF
python3 gen_languages.py > languages.go
go build -o my_scc main.go counter.go languages.go
./my_scc test.c
"}

